 content.innerHTML=`<section class="panel"><div class="panel-header"><h2>Bookings & availability</h2><button class="button secondary" id="block-time">Block time +</button></div><div class="form-grid">${field('Date','date','date',dayKey(),'id="admin-date" required')}<label class="field">Space<select id="admin-room"><option value="">All spaces</option>${options(rooms.map(s=>[s.id,s.name]),'')}</select></label></div><div id="agenda"></div><div id="blocks"></div></section><section class="panel"><h2>Google Calendar</h2><p class="hint">Bookings are managed here and synced to Google. Busy events created in Google block new requests. Changes to booking events should be made here.</p><div class="table-wrap"><table><thead><tr><th>Space</th><th>Calendar status</th><th>Action</th></tr></thead><tbody>${rooms.map(s=>{const c=connections.find(x=>x.space_id===s.id);return `<tr><td>${e(s.name)}</td><td>${c?e(c.sync_error||(!c.synced_at?'Waiting for first sync':`Last checked ${dateLabel(c.synced_at)}, ${timeLabel(c.synced_at)} EAT`)):'Not connected'}</td><td>${!c?`<button class="text-button" data-connect="${s.id}">Connect calendar</button>`:''}</td></tr>`;}).join('')}</tbody></table></div><p class="hint">Calendar connections require the Google integration to be configured. A stale or failed connection pauses new online bookings for that space.</p></section>`;
 const date=document.querySelector('#admin-date'),room=document.querySelector('#admin-room');
 let generation=0;
 async function agenda(){const token=++generation;const start=`${date.value}T00:00:00+03:00`,end=new Date(new Date(start).getTime()+86400000).toISOString();let q=db.from('bookings').select('*,profiles(full_name,email)').lt('starts_at',end).gt('ends_at',start).order('starts_at').limit(200);let blocksQuery=db.from('space_blocks').select('*').lt('starts_at',end).gt('ends_at',start).order('starts_at').limit(200);if(room.value){q=q.eq('space_id',room.value);blocksQuery=blocksQuery.eq('space_id',room.value);}const [bookings,blocks]=await Promise.all([result(q),result(blocksQuery)]);if(token!==generation)return;
  document.querySelector('#agenda').innerHTML=bookings.length?`<div class="table-wrap"><table><thead><tr><th>Time · EAT</th><th>Space / member</th><th>Status</th><th>Actions</th></tr></thead><tbody>${bookings.map(b=>`<tr><td>${timeLabel(b.starts_at)}–${timeLabel(b.ends_at)}</td><td>${e(b.space_name)}<small>${e(b.profiles.full_name||b.profiles.email)}</small>${b.note?`<small>Note: ${e(b.note)}</small>`:''}</td><td><span class="badge">${e(b.status)}</span><small>${b.use_allowance?'Allowance':money(b.price)}</small></td><td><div class="actions">${b.status==='requested'?`<button class="text-button" data-status="confirmed" data-id="${b.id}">Confirm</button>`:''}${b.status==='confirmed'&&new Date(b.ends_at)<=new Date()?`<button class="text-button" data-status="completed" data-id="${b.id}">Completed</button><button class="text-button" data-status="no_show" data-id="${b.id}">No-show</button>`:''}${['requested','confirmed'].includes(b.status)?`<button class="text-button" data-status="cancelled" data-id="${b.id}">Cancel</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No bookings on this date.</p>';
  document.querySelector('#blocks').innerHTML=blocks.length?`<h3>Blocked times</h3>${blocks.map(b=>`<div class="booking-card"><div><b>${e(rooms.find(s=>s.id===b.space_id)?.name||'Space')}</b><p>${timeLabel(b.starts_at)}–${timeLabel(b.ends_at)} · ${b.source==='google'?'Google Calendar':e(b.reason)}</p></div>${b.source==='staff'?`<button class="text-button" data-remove-block="${b.id}">Remove block</button>`:''}</div>`).join('')}`:'';
  content.querySelectorAll('[data-status]').forEach(button=>button.onclick=()=>{const status=button.dataset.status;modal(`${status==='cancelled'?'Cancel':status==='confirmed'?'Confirm':status==='no_show'?'Mark no-show for':'Complete'} booking?`,`<form>${status==='cancelled'?field('Reason','reason','text','','required minlength="3" maxlength="500"'):'<p>This updates the booking status and its allowance usage.</p>'}<p><button class="button">Save status</button></p></form>`,async f=>{await rpc('set_booking_status',{p_id:button.dataset.id,p_status:status,p_reason:f.get('reason')||''});message('Booking updated.');await agenda();});});
  content.querySelectorAll('[data-remove-block]').forEach(button=>button.onclick=()=>modal('Remove this block?',`<form><p>This time will become available if it meets the space’s booking rules.</p><button class="button">Remove block</button></form>`,async()=>{await rpc('remove_block',{p_id:button.dataset.removeBlock});await agenda();}));
 }
 date.onchange=()=>run(agenda);room.onchange=()=>run(agenda);await agenda();
 document.querySelector('#block-time').onclick=()=>modal('Block availability',`<form class="form-grid"><label class="field full">Space<select name="space" required>${options(rooms.map(s=>[s.id,s.name]),room.value)}</select></label>${field('From (Nairobi time)','start','datetime-local',`${date.value}T09:00`,'required step="1800"')}${field('Until (Nairobi time)','end','datetime-local',`${date.value}T18:00`,'required step="1800"')}<div class="full">${field('Reason','reason','text','','required minlength="3" maxlength="500"')}</div><div class="full"><button class="button">Block time</button></div></form>`,async f=>{await rpc('add_block',{p_space:f.get('space'),p_start:f.get('start')+':00+03:00',p_end:f.get('end')+':00+03:00',p_reason:f.get('reason')});message('Time blocked.');await agenda();});
