 content.innerHTML=`<section class="panel"><h2>Members & clients</h2><form id="member-search" class="actions"><label class="field">Search by name<input name="query" type="search" maxlength="150" placeholder="Member name"></label><button class="button secondary">Search</button></form><div id="members-list"></div></section>`;
