  async function find(){const date=dialog.querySelector('#payment-date').value;const start=`${date}T00:00:00+03:00`,end=new Date(new Date(start).getTime()+86400000).toISOString();const bs=await result(db.from('bookings').select('*,profiles(full_name,email)').gte('starts_at',start).lt('starts_at',end).neq('status','cancelled').gt('price',0).limit(100));dialog.querySelector('#payment-bookings').innerHTML=bs.length?bs.map(b=>`<p><button type="button" class="text-button" data-pick="${b.id}">${e(b.profiles.full_name||b.profiles.email)} · ${e(b.space_name)} · ${timeLabel(b.starts_at)}</button></p>`).join(''):'<p class="hint">No paid-rate bookings on this date.</p>';dialog.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{dialog.querySelector('[name=booking]').value=b.dataset.pick;});}
