 const dateInput=document.querySelector('#booking-date'),duration=document.querySelector('#booking-duration'),board=document.querySelector('#member-calendar'),allowance=document.querySelector('#use-allowance'),submit=document.querySelector('#request-button');dateInput.min=dayKey();dateInput.max=dayKey(new Date(Date.now()+89*86400000));
 const summary=()=>{const s=selected?.room;if(!s){document.querySelector('#booking-summary').innerHTML='<p class="muted">Choose an open slot.</p>';submit.disabled=true;return;}const mins=Number(duration.value),tier=balances?.production.tier,discount=tier==='midi'?0.7:tier==='sana'?0.5:1;document.querySelector('#booking-summary').innerHTML=`<img class="summary-image" src="${e(safeImage(s.image_url))}" alt="${e(s.image_alt)}"><h3>${e(s.name)}</h3><dl class="summary-list"><div><dt>Date</dt><dd>${e(dateInput.value)}</dd></div><div><dt>Time</dt><dd>${timeLabel(selected.slot.starts_at)}–${timeLabel(selected.slot.ends_at)}</dd></div><div><dt>Estimated total</dt><dd>${allowance.checked?'Membership allowance':money(s.hourly_rate*mins/60*discount)}</dd></div></dl>`;submit.disabled=false;};
 async function load(){const id=++loadId;selected=null;balances=null;allowance.checked=false;allowance.disabled=true;summary();board.innerHTML='<p class="muted">Checking every connected space…</p>';const mins=Number(duration.value);const rows=await Promise.all(rooms.map(async room=>{try{return {room,slots:await rpc('available_slots',{p_space:room.id,p_day:dateInput.value,p_minutes:mins})};}catch{return {room,slots:[]};}}));if(id!==loadId)return;board.innerHTML=rows.map(({room,slots})=>`<article class="calendar-room"><div class="calendar-room-info"><img src="${e(safeImage(room.image_url))}" alt=""><div><h3>${e(room.name)}</h3><p>${money(room.hourly_rate)} / hour · ${room.capacity} ${room.capacity===1?'person':'people'}</p></div></div><div class="calendar-slots">${slots.length?slots.map((slot,i)=>`<button type="button" class="calendar-slot" data-room="${room.id}" data-slot="${i}" aria-label="${e(room.name)} ${timeLabel(slot.starts_at)} to ${timeLabel(slot.ends_at)}">${timeLabel(slot.starts_at)}</button>`).join(''):'<span class="no-slots">No open slots</span>'}</div></article>`).join('');rows.forEach(({room,slots})=>board.querySelectorAll(`[data-room="${room.id}"]`).forEach(button=>button.onclick=async()=>{selected={room,slot:slots[Number(button.dataset.slot)]};board.querySelectorAll('.calendar-slot').forEach(x=>x.setAttribute('aria-pressed',x===button));balances=await rpc('my_allowances',{p_date:`${dateInput.value}T12:00:00+03:00`});allowance.disabled=balances.production.tier!=='student'&&(room.allowance_kind==='none'||(room.allowance_kind==='production'?balances.production.tier==='free':balances.studio.tier==='free'));document.querySelector('#allowance-hint').textContent=balances.production.tier==='student'?`${balances.production.remaining/60} shared student hours remaining this week across all spaces.`:room.allowance_kind==='studio'?`${balances.studio.remaining} two-hour sessions remaining this week.`:room.allowance_kind==='production'?`${balances.production.remaining/60} production hours remaining this week.`:'Membership allowances do not apply to this space.';requestKey=crypto.randomUUID();summary();}));}
